import{_ as t,o as a,c as o,a2 as d}from"./chunks/framework.7R1OEGYz.js";const u=JSON.parse('{"title":"Chart values for operators","description":"","frontmatter":{},"headers":[],"relativePath":"chart-values.md","filePath":"chart-values.md","lastUpdated":1793918544000}'),s={name:"chart-values.md"};function r(n,e,i,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="chart-values-for-operators" tabindex="-1">Chart values for operators <a class="header-anchor" href="#chart-values-for-operators" aria-label="Permalink to &quot;Chart values for operators&quot;">​</a></h1><p>The Helm chart has many values; this page covers the ones an operator of Open AgentHub 1.14.1 most often needs to set or change. Defaults are those of <code>helm/open-agenthub/values.yaml</code> at v1.14.1. For everything else, read the <a href="https://github.com/open-agenthub/open-agenthub/blob/main/helm/open-agenthub/values.yaml" target="_blank" rel="noreferrer">values file</a> itself; its comments explain each key.</p><p><strong>Edition:</strong> Community (Enterprise-only values are marked) · <strong>Who:</strong> operator</p><div class="tip custom-block"><p class="custom-block-title">Keep a values file</p><p>Pass your settings with <code>-f my-values.yaml</code> rather than <code>--reuse-values</code>, so new defaults arrive with each upgrade. See <a href="/docs/upgrading">Upgrading</a>.</p></div><h2 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Value</th><th>Default</th><th>What it does, when to change it</th></tr></thead><tbody><tr><td><code>image.registry</code></td><td><code>ghcr.io/open-agenthub/open-agenthub</code></td><td>Base path of every component image. Change it for a mirror or your own build.</td></tr><tr><td><code>image.tag</code></td><td><code>latest</code></td><td>Selects the backend, frontend and all five agent runtimes at once, so they always move together. Pin a release tag in production. Quote a commit-SHA tag, or YAML may read it as a number.</td></tr><tr><td><code>agent.pullPolicy</code></td><td><code>IfNotPresent</code></td><td>Use <code>Always</code> if you deploy a moving tag such as <code>latest</code>, so nodes do not keep a stale image.</td></tr><tr><td><code>agent.autoUpdateRuntimeImages</code></td><td><code>false</code></td><td>Replaces an outdated runtime image in a running session automatically, but only when the session confirms it is idle. Interactive sessions only; autonomous runs are never restarted, and object storage is required. Sessions can override it under <strong>Edit session → Automatic runtime image updates</strong>. Otherwise the owner uses <strong>Update now</strong>.</td></tr></tbody></table><h2 id="backend-and-database" tabindex="-1">Backend and database <a class="header-anchor" href="#backend-and-database" aria-label="Permalink to &quot;Backend and database&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Value</th><th>Default</th><th>What it does, when to change it</th></tr></thead><tbody><tr><td><code>backend.replicas</code></td><td><code>2</code></td><td>Backend pods. Telegram or Signal (<a href="/docs/chat">Chat</a>) need exactly <code>1</code>; the chart refuses to render otherwise.</td></tr><tr><td><code>backend.database.maxPoolSize</code></td><td><code>20</code></td><td>Shared Postgres pool per replica. Overrides a <code>Maximum Pool Size</code> in <code>externalDatabase.connectionString</code>.</td></tr><tr><td><code>backend.database.lockPoolSize</code></td><td><code>10</code></td><td>Separate pool for connections that hold a database lock (integrated browser starts, token refreshes, sweeps, role changes).</td></tr><tr><td><code>externalDatabase.connectionString</code></td><td>empty</td><td>Your own Postgres, used when <code>postgres.enabled=false</code>, e.g. <code>Host=db.your-org.example;Database=agenthub;Username=agenthub;Password=...</code>.</td></tr><tr><td><code>postgres.enabled</code></td><td><code>true</code></td><td>Runs the bundled Postgres. Requires <code>postgres.password</code>.</td></tr><tr><td><code>postgres.persistence</code> / <code>postgres.storage</code></td><td><code>true</code> / <code>5Gi</code></td><td>PVC for the bundled database. <code>persistence: false</code> uses an emptyDir and loses data on restart: testing only.</td></tr><tr><td><code>postgres.appArmorUnconfined</code></td><td><code>false</code></td><td>Last resort, see below.</td></tr></tbody></table><h3 id="shared-protection-keys" tabindex="-1">Shared protection keys <a class="header-anchor" href="#shared-protection-keys" aria-label="Permalink to &quot;Shared protection keys&quot;">​</a></h3><p><strong>Community and Enterprise · operator.</strong> The release containing <a href="https://github.com/open-agenthub/open-agenthub/issues/458" target="_blank" rel="noreferrer">issue #458</a> stores the backend&#39;s Data Protection key ring in Postgres. Replicas and replacement pods use the same keys for stored MCP secrets, webhook secrets, gateway tokens and cleanup previews.</p><table tabindex="0"><thead><tr><th>Value</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>dataProtection.existingSecret</code></td><td>empty</td><td>Empty: Helm generates and retains <code>agenthub-data-protection</code>. Set a Secret name to supply your own RSA PEM certificate (<code>tls.crt</code>) and matching private key (<code>tls.key</code>), at least 2048 bits. The Secret must be in the backend namespace.</td></tr></tbody></table><p>Normal <code>helm install</code> / <code>helm upgrade</code> reuses the generated Secret. It is deliberately retained on uninstall: keep it if you intend to restore or reconnect the same database. <strong>Back up Postgres and this Secret together.</strong> Losing or replacing the wrapping identity prevents the backend from reading the existing ring; startup stops with an error.</p><p>For a declarative deployment or offline <code>helm template</code>, create and manage a stable Secret first, because an offline render cannot look up an existing generated Secret:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dataProtection</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  existingSecret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">my-data-protection</span></span></code></pre></div><p>Create the Secret from your certificate and private-key files:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> agenthub</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> secret</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tls</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-data-protection</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cert=certificate.pem</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key=private-key.pem</span></span></code></pre></div><p>This certificate wraps stored keys; it does not need to be your ingress TLS certificate. Restrict access to the private key. Restart backend pods after changing Secret input. Do not replace the certificate as a routine rotation: historical ring entries and database backups still need the old private key. Overlapping decryption certificates require operator-provided backend configuration; see the <a href="https://github.com/open-agenthub/open-agenthub/blob/main/docs/data-protection.md" target="_blank" rel="noreferrer">rotation decision</a>.</p><p>Outside the chart, every backend requires the same <code>DataProtection__CertificatePem</code> and <code>DataProtection__PrivateKeyPem</code> environment values. No key directory in HOME is needed. See <a href="/docs/upgrading#shared-protection-keys-and-secret-recovery">upgrade recovery</a>.</p><h3 id="the-connection-budget" tabindex="-1">The connection budget <a class="header-anchor" href="#the-connection-budget" aria-label="Permalink to &quot;The connection budget&quot;">​</a></h3><p>Each replica uses at most <code>maxPoolSize + lockPoolSize + 2</code> connections: one for change notifications, and one for the schema migration lock during startup. With the defaults that is 32 per replica, <strong>64 for two replicas, and briefly 96</strong> while a rolling update runs one extra (surge) pod. In practice a replica holds about 3 connections after startup and about 20 under load, but the database has to allow for the ceiling.</p><p>Many managed Postgres plans allow only <code>max_connections=100</code>, a few of them reserved by the provider. Backups, migrations and other clients come on top. On such a plan, lower <code>maxPoolSize</code> (say to 15) or raise <code>max_connections</code> <strong>before</strong> you add a replica.</p><p><code>lockPoolSize</code> caps how many locked operations one replica can run at the same moment. A request that finds the lock pool full waits up to 15 seconds, then fails.</p><h3 id="bundled-postgres" tabindex="-1">Bundled Postgres <a class="header-anchor" href="#bundled-postgres" aria-label="Permalink to &quot;Bundled Postgres&quot;">​</a></h3><p>The bundled database is meant for evaluation and small installs. Since 1.14.0 it is initialised in an init container, which avoids a shutdown signal that some hosts&#39; AppArmor profile denies. A volume whose data directory already has a non-empty <code>PG_VERSION</code> file is left alone, so existing databases are not initialised again.</p><p>On such a host, later operations that need the same signal can still fail: a manual <code>CHECKPOINT</code> and crash recovery, and probably backups that request a checkpoint. <strong>For production, use an external database.</strong> <code>postgres.appArmorUnconfined: true</code> runs the bundled Postgres pod without AppArmor confinement. That weakens its security profile, so use it only as a last resort. The decision record <a href="https://github.com/open-agenthub/open-agenthub/blob/main/docs/postgres-startup.md" target="_blank" rel="noreferrer">postgres-startup.md</a> explains the trade-off.</p><h2 id="object-storage-and-session-egress" tabindex="-1">Object storage and session egress <a class="header-anchor" href="#object-storage-and-session-egress" aria-label="Permalink to &quot;Object storage and session egress&quot;">​</a></h2><p>Object storage holds session state, scrollback, transcripts and files. Without it, sessions run, but cannot be resumed and have no history.</p><table tabindex="0"><thead><tr><th>Value</th><th>Default</th><th>What it does, when to change it</th></tr></thead><tbody><tr><td><code>objectStorage.enabled</code></td><td><code>false</code></td><td>Deploys a single-node S3-compatible store in the cluster and wires <code>s3.*</code> to it. It needs a one-time bootstrap (layout, bucket, key); the README&#39;s object storage section has the commands.</td></tr><tr><td><code>s3.serviceUrl</code></td><td>empty</td><td>Your own S3-compatible endpoint, as the backend reaches it. Set values win over the bundled store.</td></tr><tr><td><code>s3.publicUrl</code></td><td>empty</td><td>Leave empty to stream browser uploads and downloads through the API.</td></tr><tr><td><code>agent.storageEgress.cidrs</code></td><td><code>[]</code></td><td>Destination networks for external storage reached <strong>by DNS name on a port other than 80 or 443</strong>.</td></tr><tr><td><code>agent.extraEgressPorts</code></td><td><code>[]</code></td><td>Extra TCP ports session pods may reach, to <strong>any</strong> destination. Ports 53, 80, 443 and 22 are always open.</td></tr><tr><td><code>agent.trustedCaConfigMap</code></td><td>empty</td><td>ConfigMap in the sessions namespace with a PEM bundle under <code>ca.crt</code>, for storage or other endpoints behind a private CA. Applies when a session pod starts; pause and resume running sessions to pick it up.</td></tr></tbody></table><p>Session pods talk to object storage directly. The chart opens the bundled store and an external store at a literal IP address automatically. A Kubernetes network policy cannot match a DNS name, so for <code>s3.serviceUrl: https://s3.your-org.example:9000</code> set <code>agent.storageEgress.cidrs</code> to the endpoint&#39;s networks. If you cannot, <code>agent.extraEgressPorts: [9000]</code> opens that port to every destination. <code>helm install</code> and <code>helm upgrade</code> print a warning when neither is set. Sessions that cannot reach storage cannot save or restore their state.</p><h2 id="sign-in-and-network-trust" tabindex="-1">Sign-in and network trust <a class="header-anchor" href="#sign-in-and-network-trust" aria-label="Permalink to &quot;Sign-in and network trust&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Value</th><th>Default</th><th>What it does, when to change it</th></tr></thead><tbody><tr><td><code>oidc.authority</code></td><td>empty</td><td>Issuer URL of your OIDC provider. Empty means the API key below guards the instance.</td></tr><tr><td><code>oidc.clientId</code> / <code>oidc.audience</code></td><td><code>agenthub</code> / <code>agenthub</code></td><td>Client and expected <code>aud</code> claim. Empty audience skips that check.</td></tr><tr><td><code>auth.apiKey.existingSecret</code></td><td>empty</td><td>Empty: the chart generates the key into Secret <code>agenthub-api-key</code>. Set it for GitOps (<code>helm template</code>).</td></tr><tr><td><code>auth.apiKey.owner</code></td><td>empty</td><td>The user the key acts as, always an admin.</td></tr><tr><td><code>auth.insecureDevMode</code></td><td><code>false</code></td><td>No login at all. Local development only.</td></tr><tr><td><code>backend.forwardedHeaders.knownProxies</code></td><td><code>127.0.0.1,::1</code></td><td>Proxies whose <code>X-Forwarded-For</code> the backend trusts, for example to throttle wrong API keys per client.</td></tr><tr><td><code>backend.forwardedHeaders.knownNetworks</code></td><td>private ranges</td><td>Narrow both to your ingress controller&#39;s source range.</td></tr></tbody></table><p>The API key, rotation and GitOps setup are described in <a href="/docs/upgrading#installs-without-oidc-the-api-key">Upgrading</a>.</p><h2 id="sessions" tabindex="-1">Sessions <a class="header-anchor" href="#sessions" aria-label="Permalink to &quot;Sessions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Value</th><th>Default</th><th>What it does, when to change it</th></tr></thead><tbody><tr><td><code>agent.maxCpu</code> / <code>agent.maxMemory</code></td><td><code>2</code> / <code>4Gi</code></td><td>Limit of every session that sets none.</td></tr><tr><td><code>agent.cpuLimitCeiling</code> / <code>agent.memoryLimitCeiling</code></td><td>empty</td><td>Highest limit a session may set for itself. Empty means <code>maxCpu</code> / <code>maxMemory</code>. Raise them to let single sessions use more.</td></tr><tr><td><code>agent.minCpu</code> / <code>agent.minMemory</code></td><td><code>50m</code> / <code>256Mi</code></td><td>Smallest request a session may ask for. A new session requests 500m CPU and 1Gi memory unless its owner changes that.</td></tr><tr><td><code>maxRunningSessionsPerOwner</code></td><td><code>50</code></td><td>Concurrent non-terminal sessions per user. More are refused with HTTP 429.</td></tr><tr><td><code>agent.allowRootSessions</code></td><td><code>true</code></td><td>Lets users run a session as root, to install tools. It needs Pod Security &quot;baseline&quot; on the sessions namespace; set <code>false</code> to allow &quot;restricted&quot;.</td></tr><tr><td><code>agent.allowCustomImage</code></td><td><code>true</code></td><td>Lets users pick their own container image per session.</td></tr><tr><td><code>spawnMcpEnabled</code></td><td><code>true</code></td><td>The in-session sessions MCP: child sessions, messages between sessions. <a href="/docs/session-tools">Session tools</a> depend on it, and so do helper containers.</td></tr><tr><td><code>telemetry.enabled</code></td><td><code>true</code></td><td>Claude Code usage export for the <a href="/docs/usage">Usage page</a>.</td></tr></tbody></table><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Value</th><th>Default</th><th>What it does, when to change it</th></tr></thead><tbody><tr><td><code>browser.enabled</code></td><td><code>true</code></td><td>The integrated browser (<a href="/docs/browser">Browser</a>).</td></tr><tr><td><code>browser.previewPorts</code></td><td><code>[3000, 4173, 5173, 8000, 8080]</code></td><td>Ports on the session&#39;s own pod the browser may open. <code>[]</code> disables it. See <a href="/docs/preview">Preview</a>.</td></tr><tr><td><code>mcp.enabled</code></td><td><code>false</code></td><td>Remote MCP endpoint at <code>/mcp</code> for external clients. See <a href="/docs/mcp">MCP</a>.</td></tr><tr><td><code>mcp.publicUrl</code></td><td>empty</td><td>External HTTPS origin of that endpoint. Empty means it is derived from <code>ingress.host</code>.</td></tr><tr><td><code>sharing.userSuggestionsEnabled</code></td><td><code>true</code></td><td>Enterprise. The share dialog suggests users after two typed characters. <code>false</code> allows only an exact username or email.</td></tr><tr><td><code>ee.admins</code></td><td>empty</td><td>Comma-separated usernames that are always admins. See <a href="/docs/admin">Administration</a>.</td></tr></tbody></table><h2 id="licence-report-warning" tabindex="-1">Licence report warning <a class="header-anchor" href="#licence-report-warning" aria-label="Permalink to &quot;Licence report warning&quot;">​</a></h2><p><code>ee.license.reportWarningDays</code> controls how many days before the current signed licence token expires the Admin license page warns (default <code>7</code>, range <code>0</code>–<code>365</code>). Zero warns at expiry. It does not change entitlement validity or report frequency. See <a href="/docs/admin#check-renewal-health">renewal health</a>.</p>`,38)])])}const g=t(s,[["render",r]]);export{u as __pageData,g as default};
